import React, { useMemo } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend, Cell, CartesianGrid, PieChart, Pie } from "recharts";

const COLORS = ['#4ade80', '#60a5fa', '#f472b6', '#fbbf24', '#a78bfa'];

// A new, self-contained Plan class
class Plan {
  constructor(goals, disposableIncome, currentSavings) {
    this.goals = goals || [];
    this.disposableIncome = disposableIncome || 0;
    this.currentSavings = currentSavings || 0;
    this.monthlyAllocations = {};
    this.totalAllocations = {};
    this.totalMonthlyNeeded = 0;
    this.totalSavingsNeeded = 0;
    this.calculate();
  }

  calculate() {
    // Sort goals by priority
    const sortedGoals = [...this.goals].sort((a, b) => (a.priority || 0) - (b.priority || 0));
    let remainingIncome = this.disposableIncome;

    // Calculate total savings needed across all goals
    this.totalSavingsNeeded = this.goals.reduce((sum, goal) => sum + (goal.targetAmount || 0), 0);

    for (const goal of sortedGoals) {
      if (!goal || !goal.id) continue;

      const months = this.getMonthsRemaining(goal.deadline);
      const monthlyContribution = Math.max(0, (goal.targetAmount || 0) / months);

      // Allocate income
      const allocation = Math.min(monthlyContribution, remainingIncome);
      this.monthlyAllocations[goal.id] = allocation;
      remainingIncome -= allocation;

      // Calculate total allocation over the goal's lifetime
      this.totalAllocations[goal.id] = allocation * months;
    }

    // Calculate total monthly needed
    this.totalMonthlyNeeded = Object.values(this.monthlyAllocations).reduce((sum, allocation) => sum + allocation, 0);
  }

  getMonthsRemaining(deadline) {
    if (!deadline) return 1;
    const now = new Date();
    const end = new Date(deadline);
    const months = (end.getFullYear() - now.getFullYear()) * 12 + (end.getMonth() - now.getMonth());
    return Math.max(1, months);
  }
}

export default function Overview({ goals = [], income = { monthlyDisposableIncome: 0 }, currentSavings = 0 }) {
  // Create a new plan based on the props
  const plan = useMemo(() => new Plan(goals, income.monthlyDisposableIncome, currentSavings), [goals, income, currentSavings]);

  // Chart data for monthly savings
  const monthlySavingsData = useMemo(() => {
    return plan.goals.map(goal => ({
      name: goal.name,
      'Monthly Allocation': plan.monthlyAllocations[goal.id] || 0,
    }));
  }, [plan]);

  // Chart data for total savings distribution
  const totalSavingsDistribution = useMemo(() => {
    const saved = plan.currentSavings;
    const remaining = Math.max(0, plan.totalSavingsNeeded - saved);
    return [
      { name: "Total Saved", value: saved },
      { name: "Remaining", value: remaining },
    ].filter(item => item.value > 0);
  }, [plan]);

  // Total target amount
  const totalTargetAmount = plan.totalSavingsNeeded;

  // Monthly shortfall
  const shortfall = Math.max(0, plan.totalMonthlyNeeded - plan.disposableIncome);

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-4 rounded-lg shadow-lg border border-gray-200">
          <p className="font-semibold">{label}</p>
          {payload.map((entry, index) => (
            <p key={index} style={{ color: entry.color }}>
              {entry.name}: ${entry.value.toLocaleString()}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  if (!goals.length) {
    return (
      <div className="p-6">
        <div className="text-center text-gray-500">
          No goals found. Add some goals to see your savings plan.
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Bar Chart */}
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold mb-4">Monthly Savings Allocation</h2>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlySavingsData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis 
                  dataKey="name" 
                  angle={-45} 
                  textAnchor="end" 
                  height={100}
                  interval={0}
                />
                <YAxis />
                <Tooltip content={<CustomTooltip />} />
                <Legend />
                <Bar dataKey="Monthly Allocation" fill="#4ade80" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Pie Chart */}
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold mb-4">Total Savings Distribution</h2>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={totalSavingsDistribution}
                  dataKey="value"
                  nameKey="name"
                  cx="50%"
                  cy="50%"
                  outerRadius={100}
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                >
                  {totalSavingsDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mt-6">
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Total Target Amount</h3>
          <p className="text-2xl font-semibold mt-2">${totalTargetAmount.toLocaleString()}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Monthly Savings Needed</h3>
          <p className="text-2xl font-semibold mt-2">${(plan.totalMonthlyNeeded || 0).toLocaleString()}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Monthly Shortfall</h3>
          <p className="text-2xl font-semibold mt-2 text-red-500">${shortfall.toLocaleString()}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Total Saved</h3>
          <p className="text-2xl font-semibold mt-2">${currentSavings.toLocaleString()}</p>
        </div>
      </div>
    </div>
  );
}
